import{_ as s,o as n,c as e,a0 as t}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Sandbox Architecture","description":"","frontmatter":{"title":"Sandbox Architecture"},"headers":[],"relativePath":"design/sandbox.md","filePath":"design/sandbox.md"}'),o={name:"design/sandbox.md"};function r(i,a,d,p,l,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="sandbox-architecture" tabindex="-1">Sandbox Architecture <a class="header-anchor" href="#sandbox-architecture" aria-label="Permalink to &quot;Sandbox Architecture&quot;">​</a></h1><blockquote><p>Source: <code>cmd/lattice/cmd/sandbox/</code>, <code>internal/agent/gvisor/</code></p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>lattice sandbox start</code> fuses the <strong>gVisor user-space network stack</strong> with the <strong>Lattice WireGuard overlay</strong>. AI agent processes run as ordinary users with no kernel capabilities, yet obtain a full Lattice network identity — NATS registration, ICE hole-punching, LRP relay fallback — identical to a regular node.</p><h2 id="comparison-with-regular-node" tabindex="-1">Comparison with Regular Node <a class="header-anchor" href="#comparison-with-regular-node" aria-label="Permalink to &quot;Comparison with Regular Node&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Regular Node (<code>lattice up</code>)</th><th>Sandbox (<code>lattice sandbox start</code>)</th></tr></thead><tbody><tr><td>Isolation</td><td>None (host process)</td><td>gVisor user-space netstack</td></tr><tr><td>Privilege</td><td>root / <code>CAP_NET_ADMIN</code></td><td><strong>Zero-privilege</strong></td></tr><tr><td>Network stack</td><td>Kernel TUN (<code>wf0</code>)</td><td>gVisor <code>pkg/tcpip</code> + TUNAdapter</td></tr><tr><td>WireGuard</td><td>Kernel <code>wgctrl</code></td><td><code>golang.zx2c4.com/wireguard</code> (user-space)</td></tr><tr><td>Provisioner</td><td><code>KernelProvisioner</code> (iptables/eBPF)</td><td><code>SandboxProvisioner</code> (no iptables)</td></tr><tr><td>Registration</td><td>HTTP or NATS</td><td>NATS only (<code>RegisterSandboxViaNATS</code>)</td></tr><tr><td>Credential persistence</td><td>None</td><td>JSON file (<code>/etc/lattice/sandbox-credentials.json</code>)</td></tr><tr><td>Audit log</td><td>eBPF ring buffer (Pro)</td><td>JSONL file (<code>/tmp/lattice-audit-&lt;name&gt;.jsonl</code>)</td></tr><tr><td>Egress policy</td><td>eBPF TC (Pro) / iptables</td><td><code>EgressFilter</code> (Pro sandbox only)</td></tr><tr><td>Inbound forwarding</td><td>None</td><td><code>ForwardListener</code> (Pro)</td></tr><tr><td>HTTP proxy</td><td>None</td><td>HTTP forward proxy (Pro)</td></tr><tr><td>ICE / LRP</td><td>✅ Full support</td><td>✅ Full support (shared infrastructure)</td></tr></tbody></table><h2 id="network-architecture" tabindex="-1">Network Architecture <a class="header-anchor" href="#network-architecture" aria-label="Permalink to &quot;Network Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌─────────────────────────────┐</span></span>
<span class="line"><span>                │       gVisor Sandbox         │</span></span>
<span class="line"><span>                │                              │</span></span>
<span class="line"><span>  Agent process ──▶  gVisor netstack (tcpip)   │</span></span>
<span class="line"><span>  connect()         │                          │</span></span>
<span class="line"><span>                │  [Pro] EgressFilter          │</span></span>
<span class="line"><span>                │   │                          │</span></span>
<span class="line"><span>                │   TUNAdapter (channel bridge)│</span></span>
<span class="line"><span>                │   │                          │</span></span>
<span class="line"><span>                │   wireguard-go Device        │</span></span>
<span class="line"><span>                └──────────┬───────────────────┘</span></span>
<span class="line"><span>                           │ UDP :51820</span></span>
<span class="line"><span>                ┌──────────▼───────────────────┐</span></span>
<span class="line"><span>                │   FilteringUDPMux             │</span></span>
<span class="line"><span>                │   STUN ──▶ ICE agent          │</span></span>
<span class="line"><span>                │   non-STUN ──▶ WG DefaultBind │</span></span>
<span class="line"><span>                └──────────┬───────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>          ┌────────────────┴──────────────┐</span></span>
<span class="line"><span>          │  ICE succeeds                 │  ICE fails</span></span>
<span class="line"><span>          ▼                               ▼</span></span>
<span class="line"><span>    Direct P2P                    LRP relay (QUIC/TCP)</span></span></code></pre></div><p>The sandbox uses the <strong>same signaling path</strong> as a regular node. gVisor replaces only the kernel TUN device.</p><h2 id="code-structure" tabindex="-1">Code Structure <a class="header-anchor" href="#code-structure" aria-label="Permalink to &quot;Code Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmd/lattice/cmd/sandbox/</span></span>
<span class="line"><span>├── sandbox.go              # Command definition (--name, --server-url, --token)</span></span>
<span class="line"><span>├── sandbox_shared.go       # No build tag — shared utilities (credential I/O, fileAuditWriter)</span></span>
<span class="line"><span>├── sandbox_community.go    # //go:build !pro — full community implementation</span></span>
<span class="line"><span>└── sandbox_pro.go          # //go:build pro  — Pro-only extensions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>internal/agent/gvisor/</span></span>
<span class="line"><span>├── sandbox.go              # gvisor.New() entry point, Config{ID, LocalIP, PolicyChecker, AuditWriter}</span></span>
<span class="line"><span>├── tun_adapter.go          # NewTUNAdapter: gVisor ↔ wireguard-go packet bridge</span></span>
<span class="line"><span>├── provisioner.go          # SandboxProvisioner (no iptables, replaces KernelProvisioner)</span></span>
<span class="line"><span>└── shimfwd/</span></span>
<span class="line"><span>    ├── egress_filter.go    # EgressFilter (CIDR allowlist/denylist, implements PolicyChecker)</span></span>
<span class="line"><span>    ├── forward_listener.go # ForwardListener (overlay port → host address forwarding)</span></span>
<span class="line"><span>    └── audit_writer.go     # AuditWriter interface + AuditEvent struct</span></span></code></pre></div><h2 id="community-vs-pro-build-tags" tabindex="-1">Community vs Pro Build Tags <a class="header-anchor" href="#community-vs-pro-build-tags" aria-label="Permalink to &quot;Community vs Pro Build Tags&quot;">​</a></h2><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sandbox_community.go</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//go:build !pro</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sandbox_pro.go</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//go:build pro</span></span></code></pre></div><p>Community stubs for Pro features return <code>&quot;... is a Pro feature&quot;</code> errors. Build with <code>make EDITION=pro build</code> to include Pro code.</p>`,14)])])}const h=s(o,[["render",r]]);export{g as __pageData,h as default};
